		["Would you like to learn {animate dead} magic spell for 1200 gold?"] = "Quer aprender a magia {animate dead} por 1200 de ouro?",
		["Would you like to learn {annihilation} magic spell for 20000 gold?"] = "Quer aprender a magia {annihilation} por 20000 de ouro?",
		["Would you like to learn {apprentice's strike} magic spell for free?"] = "Quer aprender a magia {apprentice's strike} de graça?",
